18	package org.apache.hadoop.hdfs.server.blockmanagement;
19	
20	import org.apache.hadoop.conf.Configurable;
21	import org.apache.hadoop.conf.Configuration;
22	import org.apache.hadoop.hdfs.DFSConfigKeys;
23	import org.apache.hadoop.hdfs.server.namenode.Namesystem;
24	import org.slf4j.Logger;
25	import org.slf4j.LoggerFactory;
26	
27	import java.util.ArrayDeque;
28	import java.util.Queue;
29	
30	/**
31	 * This abstract class provides some base methods which are inherited by
32	 * the DatanodeAdmin BackOff and Default Monitors, which control decommission
33	 * and maintenance mode.
34	 */
35	public abstract class DatanodeAdminMonitorBase
36	    implements DatanodeAdminMonitorInterface, Configurable {
37	
38	  protected BlockManager blockManager;
39	  protected Namesystem namesystem;
40	  protected DatanodeAdminManager dnAdmin;
41	  protected Configuration conf;
42	
43	  protected final Queue<DatanodeDescriptor> pendingNodes = new ArrayDeque<>();
44	
45	  /**
46	   * The maximum number of nodes to track in outOfServiceNodeBlocks.
47	   * A value of 0 means no limit.
48	   */
49	  protected int maxConcurrentTrackedNodes;
50	
51	  private static final Logger LOG =
52	      LoggerFactory.getLogger(DatanodeAdminMonitorBase.class);
53	
54	  /**
55	   * Set the cluster namesystem.
56	   *
57	   * @param ns The namesystem for the cluster
58	   */
59	  @Override
60	  public void setNameSystem(Namesystem ns) {
61	    this.namesystem = ns;
62	  }
63	
64	  /**
65	   * Set the blockmanager for the cluster.
66	   *
67	   * @param bm The cluster BlockManager
68	   */
69	  @Override
70	  public void setBlockManager(BlockManager bm) {
71	    this.blockManager = bm;
72	  }
73	
74	  /**
75	   * Set the DatanodeAdminManager instance in use in the namenode.
76	   *
77	   * @param admin The current DatanodeAdminManager
78	   */
79	  @Override
80	  public void setDatanodeAdminManager(DatanodeAdminManager admin) {
81	    this.dnAdmin = admin;
82	  }
83	
84	  /**
85	   * Used by the Configurable interface, which is used by ReflectionUtils
86	   * to create an instance of the monitor class. This method will be called to
87	   * pass the Configuration to the new object.
88	   *
89	   * @param conf configuration to be used
90	   */
91	  @Override
92	  public void setConf(Configuration conf) {
93	    this.conf = conf;
94	    this.maxConcurrentTrackedNodes = conf.getInt(
95	        DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_MAX_CONCURRENT_TRACKED_NODES,
96	        DFSConfigKeys
97	            .DFS_NAMENODE_DECOMMISSION_MAX_CONCURRENT_TRACKED_NODES_DEFAULT);
98	    if (this.maxConcurrentTrackedNodes < 0) {
99	      LOG.error("{} is set to an invalid value, it must be zero or greater. "+
100	              "Defaulting to {}",
101	          DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_MAX_CONCURRENT_TRACKED_NODES,
102	          DFSConfigKeys
103	              .DFS_NAMENODE_DECOMMISSION_MAX_CONCURRENT_TRACKED_NODES_DEFAULT);
104	      this.maxConcurrentTrackedNodes =
105	          DFSConfigKeys
106	              .DFS_NAMENODE_DECOMMISSION_MAX_CONCURRENT_TRACKED_NODES_DEFAULT;
107	    }
108	    processConf();
109	  }
110	
111	  /**
112	   * Get the current Configuration stored in this object.
113	   *
114	   * @return Configuration used when the object was created
115	   */
116	  @Override
117	  public Configuration getConf() {
118	    return this.conf;
119	  }
120	
121	  /**
122	   * Abstract method which must be implemented by the sub-classes to process
123	   * set various instance variables from the Configuration passed at object
124	   * creation time.
125	   */
126	  protected abstract void processConf();
127	
128	  /**
129	   * Start tracking a node for decommission or maintenance. The given Datanode
130	   * will be queued for later processing in pendingNodes. This method must be
131	   * called under the namenode write lock.
132	   * @param dn The datanode to start tracking
133	   */
134	  @Override
135	  public void startTrackingNode(DatanodeDescriptor dn) {
136	    pendingNodes.add(dn);
137	  }
138	
139	  /**
140	   * Get the number of datanodes nodes in the pending queue. Ie the count of
141	   * nodes waiting to decommission but have not yet started the process.
142	   *
143	   * @return The count of pending nodes
144	   */
145	  @Override
146	  public int getPendingNodeCount() {
147	    return pendingNodes.size();
148	  }
149	
150	  @Override
151	  public Queue<DatanodeDescriptor> getPendingNodes() {
152	    return pendingNodes;
153	  }
154	}
