18	package org.apache.hadoop.hdfs.server.blockmanagement;
19	
20	import org.apache.hadoop.thirdparty.com.google.common.base.Preconditions;
21	import org.apache.hadoop.hdfs.DFSConfigKeys;
22	import org.apache.hadoop.hdfs.protocol.DatanodeID;
23	import org.apache.hadoop.hdfs.server.namenode.INode;
24	import org.apache.hadoop.hdfs.server.namenode.INodeFile;
25	import org.apache.hadoop.hdfs.server.namenode.INodeId;
26	import org.apache.hadoop.hdfs.util.CyclicIteration;
27	import org.apache.hadoop.hdfs.util.LightWeightHashSet;
28	import org.apache.hadoop.hdfs.util.LightWeightLinkedSet;
29	import org.apache.hadoop.util.ChunkedArrayList;
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	
33	import java.util.AbstractList;
34	import java.util.TreeMap;
35	import java.util.ArrayList;
36	import java.util.Map;
37	import java.util.List;
38	import java.util.Iterator;
39	
40	/**
41	 * Checks to see if datanodes have finished DECOMMISSION_INPROGRESS or
42	 * ENTERING_MAINTENANCE state.
43	 * <p>
44	 * Since this is done while holding the namesystem lock,
45	 * the amount of work per monitor tick is limited.
46	 */
47	
48	public class DatanodeAdminDefaultMonitor extends DatanodeAdminMonitorBase
49	    implements DatanodeAdminMonitorInterface {
50	
51	  /**
52	   * Map containing the DECOMMISSION_INPROGRESS or ENTERING_MAINTENANCE
53	   * datanodes that are being tracked so they can be be marked as
54	   * DECOMMISSIONED or IN_MAINTENANCE. Even after the node is marked as
55	   * IN_MAINTENANCE, the node remains in the map until
56	   * maintenance expires checked during a monitor tick.
57	   * <p/>
58	   * This holds a set of references to the under-replicated blocks on the DN
59	   * at the time the DN is added to the map, i.e. the blocks that are
60	   * preventing the node from being marked as decommissioned. During a monitor
61	   * tick, this list is pruned as blocks becomes replicated.
62	   * <p/>
63	   * Note also that the reference to the list of under-replicated blocks
64	   * will be null on initial add
65	   * <p/>
66	   * However, this map can become out-of-date since it is not updated by block
67	   * reports or other events. Before being finally marking as decommissioned,
68	   * another check is done with the actual block map.
69	   */
70	  private final TreeMap<DatanodeDescriptor, AbstractList<BlockInfo>>
71	      outOfServiceNodeBlocks;
72	
73	  /**
74	   * The maximum number of blocks to check per tick.
75	   */
76	  private int numBlocksPerCheck;
77	
78	  /**
79	   * The number of blocks that have been checked on this tick.
80	   */
81	  private int numBlocksChecked = 0;
82	  /**
83	   * The number of blocks checked after (re)holding lock.
84	   */
85	  private int numBlocksCheckedPerLock = 0;
86	  /**
87	   * The number of nodes that have been checked on this tick. Used for
88	   * statistics.
89	   */
90	  private int numNodesChecked = 0;
91	  /**
92	   * The last datanode in outOfServiceNodeBlocks that we've processed.
93	   */
94	  private DatanodeDescriptor iterkey = new DatanodeDescriptor(
95	      new DatanodeID("", "", "", 0, 0, 0, 0));
96	
97	  private static final Logger LOG =
98	      LoggerFactory.getLogger(DatanodeAdminDefaultMonitor.class);
99	
100	  DatanodeAdminDefaultMonitor() {
101	    this.outOfServiceNodeBlocks = new TreeMap<>();
102	  }
103	
104	  @Override
105	  protected void processConf() {
106	    numBlocksPerCheck = conf.getInt(
107	        DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_BLOCKS_PER_INTERVAL_KEY,
108	        DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_BLOCKS_PER_INTERVAL_DEFAULT);
109	    if (numBlocksPerCheck <= 0) {
110	      LOG.error("{} must be greater than zero. Defaulting to {}",
111	          DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_BLOCKS_PER_INTERVAL_KEY,
112	          DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_BLOCKS_PER_INTERVAL_DEFAULT);
113	      numBlocksPerCheck =
114	          DFSConfigKeys.DFS_NAMENODE_DECOMMISSION_BLOCKS_PER_INTERVAL_DEFAULT;
115	    }
116	    LOG.info("Initialized the Default Decommission and Maintenance monitor");
117	  }
118	
119	  private boolean exceededNumBlocksPerCheck() {
120	    LOG.trace("Processed {} blocks so far this tick", numBlocksChecked);
121	    return numBlocksChecked >= numBlocksPerCheck;
122	  }
123	
124	  @Override
125	  public void stopTrackingNode(DatanodeDescriptor dn) {
126	    pendingNodes.remove(dn);
127	    outOfServiceNodeBlocks.remove(dn);
128	  }
129	
130	  @Override
131	  public int getTrackedNodeCount() {
132	    return outOfServiceNodeBlocks.size();
133	  }
134	
135	  @Override
136	  public int getNumNodesChecked() {
137	    return numNodesChecked;
138	  }
139	
140	  @Override
141	  public void run() {
142	    LOG.debug("DatanodeAdminMonitor is running.");
143	    if (!namesystem.isRunning()) {
144	      LOG.info("Namesystem is not running, skipping " +
145	          "decommissioning/maintenance checks.");
146	      return;
147	    }
148	    // Reset the checked count at beginning of each iteration
149	    numBlocksChecked = 0;
150	    numBlocksCheckedPerLock = 0;
151	    numNodesChecked = 0;
152	    // Check decommission or maintenance progress.
153	    namesystem.writeLock();
154	    try {
155	      processPendingNodes();
156	      check();
157	    } catch (Exception e) {
158	      LOG.warn("DatanodeAdminMonitor caught exception when processing node.",
159	          e);
160	    } finally {
161	      namesystem.writeUnlock();
162	    }
163	    if (numBlocksChecked + numNodesChecked > 0) {
164	      LOG.info("Checked {} blocks and {} nodes this tick. {} nodes are now " +
165	              "in maintenance or transitioning state. {} nodes pending.",
166	          numBlocksChecked, numNodesChecked, outOfServiceNodeBlocks.size(),
167	          pendingNodes.size());
168	    }
169	  }
170	
171	  /**
172	   * Pop datanodes off the pending list and into decomNodeBlocks,
173	   * subject to the maxConcurrentTrackedNodes limit.
174	   */
175	  private void processPendingNodes() {
176	    while (!pendingNodes.isEmpty() &&
177	        (maxConcurrentTrackedNodes == 0 ||
178	            outOfServiceNodeBlocks.size() < maxConcurrentTrackedNodes)) {
179	      outOfServiceNodeBlocks.put(pendingNodes.poll(), null);
180	    }
181	  }
182	
183	  private void check() {
184	    final Iterator<Map.Entry<DatanodeDescriptor, AbstractList<BlockInfo>>>
185	        it = new CyclicIteration<>(outOfServiceNodeBlocks,
186	        iterkey).iterator();
187	    final List<DatanodeDescriptor> toRemove = new ArrayList<>();
188	
189	    while (it.hasNext() && !exceededNumBlocksPerCheck() && namesystem
190	        .isRunning()) {
191	      numNodesChecked++;
192	      final Map.Entry<DatanodeDescriptor, AbstractList<BlockInfo>>
193	          entry = it.next();
194	      final DatanodeDescriptor dn = entry.getKey();
195	      try {
196	        AbstractList<BlockInfo> blocks = entry.getValue();
197	        boolean fullScan = false;
198	        if (dn.isMaintenance() && dn.maintenanceExpired()) {
199	          // If maintenance expires, stop tracking it.
200	          dnAdmin.stopMaintenance(dn);
201	          toRemove.add(dn);
202	          continue;
203	        }
204	        if (dn.isInMaintenance()) {
205	          // The dn is IN_MAINTENANCE and the maintenance hasn't expired yet.
206	          continue;
207	        }
208	        if (blocks == null) {
209	          // This is a newly added datanode, run through its list to schedule
210	          // under-replicated blocks for replication and collect the blocks
211	          // that are insufficiently replicated for further tracking
212	          LOG.debug("Newly-added node {}, doing full scan to find " +
213	              "insufficiently-replicated blocks.", dn);
214	          blocks = handleInsufficientlyStored(dn);
215	          outOfServiceNodeBlocks.put(dn, blocks);
216	          fullScan = true;
217	        } else {
218	          // This is a known datanode, check if its # of insufficiently
219	          // replicated blocks has dropped to zero and if it can move
220	          // to the next state.
221	          LOG.debug("Processing {} node {}", dn.getAdminState(), dn);
222	          pruneReliableBlocks(dn, blocks);
223	        }
224	        if (blocks.size() == 0) {
225	          if (!fullScan) {
226	            // If we didn't just do a full scan, need to re-check with the
227	            // full block map.
228	            //
229	            // We've replicated all the known insufficiently replicated
230	            // blocks. Re-check with the full block map before finally
231	            // marking the datanode as DECOMMISSIONED or IN_MAINTENANCE.
232	            LOG.debug("Node {} has finished replicating current set of "
233	                + "blocks, checking with the full block map.", dn);
234	            blocks = handleInsufficientlyStored(dn);
235	            outOfServiceNodeBlocks.put(dn, blocks);
236	          }
237	          // If the full scan is clean AND the node liveness is okay,
238	          // we can finally mark as DECOMMISSIONED or IN_MAINTENANCE.
239	          final boolean isHealthy =
240	              blockManager.isNodeHealthyForDecommissionOrMaintenance(dn);
241	          if (blocks.size() == 0 && isHealthy) {
242	            if (dn.isDecommissionInProgress()) {
243	              dnAdmin.setDecommissioned(dn);
244	              toRemove.add(dn);
245	            } else if (dn.isEnteringMaintenance()) {
246	              // IN_MAINTENANCE node remains in the outOfServiceNodeBlocks to
247	              // to track maintenance expiration.
248	              dnAdmin.setInMaintenance(dn);
249	            } else {
250	              Preconditions.checkState(false,
251	                  "Node %s is in an invalid state! "
252	                      + "Invalid state: %s %s blocks are on this dn.",
253	                  dn, dn.getAdminState(), blocks.size());
254	            }
255	            LOG.debug("Node {} is sufficiently replicated and healthy, "
256	                + "marked as {}.", dn, dn.getAdminState());
257	          } else {
258	            LOG.info("Node {} {} healthy."
259	                    + " It needs to replicate {} more blocks."
260	                    + " {} is still in progress.", dn,
261	                isHealthy ? "is": "isn't", blocks.size(), dn.getAdminState());
262	          }
263	        } else {
264	          LOG.info("Node {} still has {} blocks to replicate "
265	                  + "before it is a candidate to finish {}.",
266	              dn, blocks.size(), dn.getAdminState());
267	        }
268	      } catch (Exception e) {
269	        // Log and postpone to process node when meet exception since it is in
270	        // an invalid state.
271	        LOG.warn("DatanodeAdminMonitor caught exception when processing node "
272	            + "{}.", dn, e);
273	        pendingNodes.add(dn);
274	        toRemove.add(dn);
275	      } finally {
276	        iterkey = dn;
277	      }
278	    }
279	    // Remove the datanodes that are DECOMMISSIONED or in service after
280	    // maintenance expiration.
281	    for (DatanodeDescriptor dn : toRemove) {
282	      Preconditions.checkState(dn.isDecommissioned() || dn.isInService(),
283	          "Removing node %s that is not yet decommissioned or in service!",
284	          dn);
285	      outOfServiceNodeBlocks.remove(dn);
286	    }
287	  }
288	
289	  /**
290	   * Removes reliable blocks from the block list of a datanode.
291	   */
292	  private void pruneReliableBlocks(final DatanodeDescriptor datanode,
293	                                   AbstractList<BlockInfo> blocks) {
294	    processBlocksInternal(datanode, blocks.iterator(), null, true);
295	  }
296	
297	  /**
298	   * Returns a list of blocks on a datanode that are insufficiently
299	   * replicated or require recovery, i.e. requiring recovery and
300	   * should prevent decommission or maintenance.
301	   * <p/>
302	   * As part of this, it also schedules replication/recovery work.
303	   *
304	   * @return List of blocks requiring recovery
305	   */
306	  private AbstractList<BlockInfo> handleInsufficientlyStored(
307	      final DatanodeDescriptor datanode) {
308	    AbstractList<BlockInfo> insufficient = new ChunkedArrayList<>();
309	    processBlocksInternal(datanode, datanode.getBlockIterator(),
310	        insufficient, false);
311	    return insufficient;
312	  }
313	
314	  /**
315	   * Used while checking if DECOMMISSION_INPROGRESS datanodes can be
316	   * marked as DECOMMISSIONED or ENTERING_MAINTENANCE datanodes can be
317	   * marked as IN_MAINTENANCE. Combines shared logic of pruneReliableBlocks
318	   * and handleInsufficientlyStored.
319	   *
320	   * @param datanode                    Datanode
321	   * @param it                          Iterator over the blocks on the
322	   *                                    datanode
323	   * @param insufficientList            Return parameter. If it's not null,
324	   *                                    will contain the insufficiently
325	   *                                    replicated-blocks from the list.
326	   * @param pruneReliableBlocks         whether to remove blocks reliable
327	   *                                    enough from the iterator
328	   */
329	  private void processBlocksInternal(
330	      final DatanodeDescriptor datanode,
331	      final Iterator<BlockInfo> it,
332	      final List<BlockInfo> insufficientList,
333	      boolean pruneReliableBlocks) {
334	    boolean firstReplicationLog = true;
335	    // Low redundancy in UC Blocks only
336	    int lowRedundancyBlocksInOpenFiles = 0;
337	    LightWeightHashSet<Long> lowRedundancyOpenFiles =
338	        new LightWeightLinkedSet<>();
339	    // All low redundancy blocks. Includes lowRedundancyOpenFiles.
340	    int lowRedundancyBlocks = 0;
341	    // All maintenance and decommission replicas.
342	    int outOfServiceOnlyReplicas = 0;
343	    while (it.hasNext()) {
344	      if (insufficientList == null
345	          && numBlocksCheckedPerLock >= numBlocksPerCheck) {
346	        // During fullscan insufficientlyReplicated will NOT be null, iterator
347	        // will be DN's iterator. So should not yield lock, otherwise
348	        // ConcurrentModificationException could occur.
349	        // Once the fullscan done, iterator will be a copy. So can yield the
350	        // lock.
351	        // Yielding is required in case of block number is greater than the
352	        // configured per-iteration-limit.
353	        namesystem.writeUnlock();
354	        try {
355	          LOG.debug("Yielded lock during decommission/maintenance check");
356	          Thread.sleep(0, 500);
357	        } catch (InterruptedException ignored) {
358	          return;
359	        }
360	        // reset
361	        numBlocksCheckedPerLock = 0;
362	        namesystem.writeLock();
363	      }
364	      numBlocksChecked++;
365	      numBlocksCheckedPerLock++;
366	      final BlockInfo block = it.next();
367	      // Remove the block from the list if it's no longer in the block map,
368	      // e.g. the containing file has been deleted
369	      if (blockManager.blocksMap.getStoredBlock(block) == null) {
370	        LOG.trace("Removing unknown block {}", block);
371	        it.remove();
372	        continue;
373	      }
374	
375	      long bcId = block.getBlockCollectionId();
376	      if (bcId == INodeId.INVALID_INODE_ID) {
377	        // Orphan block, will be invalidated eventually. Skip.
378	        continue;
379	      }
380	
381	      final BlockCollection bc = blockManager.getBlockCollection(block);
382	      final NumberReplicas num = blockManager.countNodes(block);
383	      final int liveReplicas = num.liveReplicas();
384	
385	      // Schedule low redundancy blocks for reconstruction
386	      // if not already pending.
387	      boolean isDecommission = datanode.isDecommissionInProgress();
388	      boolean isMaintenance = datanode.isEnteringMaintenance();
389	      boolean neededReconstruction = isDecommission ?
390	          blockManager.isNeededReconstruction(block, num) :
391	          blockManager.isNeededReconstructionForMaintenance(block, num);
392	      if (neededReconstruction) {
393	        if (!blockManager.neededReconstruction.contains(block) &&
394	            blockManager.pendingReconstruction.getNumReplicas(block) == 0 &&
395	            blockManager.isPopulatingReplQueues()) {
396	          // Process these blocks only when active NN is out of safe mode.
397	          blockManager.neededReconstruction.add(block,
398	              liveReplicas, num.readOnlyReplicas(),
399	              num.outOfServiceReplicas(),
400	              blockManager.getExpectedRedundancyNum(block));
401	        }
402	      }
403	
404	      // Even if the block is without sufficient redundancy,
405	      // it might not block decommission/maintenance if it
406	      // has sufficient redundancy.
407	      if (dnAdmin.isSufficient(block, bc, num, isDecommission, isMaintenance)) {
408	        if (pruneReliableBlocks) {
409	          it.remove();
410	        }
411	        continue;
412	      }
413	
414	      // We've found a block without sufficient redundancy.
415	      if (insufficientList != null) {
416	        insufficientList.add(block);
417	      }
418	      // Log if this is our first time through
419	      if (firstReplicationLog) {
420	        dnAdmin.logBlockReplicationInfo(block, bc, datanode, num,
421	            blockManager.blocksMap.getStorages(block));
422	        firstReplicationLog = false;
423	      }
424	      // Update various counts
425	      lowRedundancyBlocks++;
426	      if (bc.isUnderConstruction()) {
427	        INode ucFile = namesystem.getFSDirectory().getInode(bc.getId());
428	        if (!(ucFile instanceof INodeFile) ||
429	            !ucFile.asFile().isUnderConstruction()) {
430	          LOG.warn("File {} is not under construction. Skipping add to " +
431	              "low redundancy open files!", ucFile.getLocalName());
432	        } else {
433	          lowRedundancyBlocksInOpenFiles++;
434	          lowRedundancyOpenFiles.add(ucFile.getId());
435	        }
436	      }
437	      if ((liveReplicas == 0) && (num.outOfServiceReplicas() > 0)) {
438	        outOfServiceOnlyReplicas++;
439	      }
440	    }
441	
442	    datanode.getLeavingServiceStatus().set(lowRedundancyBlocksInOpenFiles,
443	        lowRedundancyOpenFiles, lowRedundancyBlocks,
444	        outOfServiceOnlyReplicas);
445	  }
446	}
