38	/**
39	 * This class implements the logic to track decommissioning and entering
40	 * maintenance nodes, ensure all their blocks are adequately replicated
41	 * before they are moved to the decommissioned or maintenance state.
42	 *
43	 * This monitor avoids flooding the replication queue with all pending blocks
44	 * and instead feeds them to the queue as the prior set complete replication.
45	 *
46	 * HDFS-14854 contains details about the overall design of this class.
47	 *
48	 */
49	public class DatanodeAdminBackoffMonitor extends DatanodeAdminMonitorBase
50	    implements DatanodeAdminMonitorInterface  {
51	  /**
52	   * Map containing the DECOMMISSION_INPROGRESS or ENTERING_MAINTENANCE
53	   * datanodes that are being tracked so they can be be marked as
54	   * DECOMMISSIONED or IN_MAINTENANCE. Even after the node is marked as
55	   * IN_MAINTENANCE, the node remains in the map until
56	   * maintenance expires checked during a monitor tick.
57	   * <p/>
58	   * This holds a set of references to the under-replicated blocks on the DN
59	   * at the time the DN is added to the map, i.e. the blocks that are
60	   * preventing the node from being marked as decommissioned. During a monitor
61	   * tick, this list is pruned as blocks becomes replicated.
62	   * <p/>
63	   * Note also that the reference to the list of under-replicated blocks
64	   * will be null on initial add
65	   * <p/>
66	   * However, this map can become out-of-date since it is not updated by block
67	   * reports or other events. Before being finally marking as decommissioned,
68	   * another check is done with the actual block map.
69	   */
70	  private HashMap<DatanodeDescriptor, HashMap<BlockInfo, Integer>>
71	      outOfServiceNodeBlocks = new HashMap<>();
72	
73	  /**
74	   * Any nodes where decommission or maintenance has been cancelled are added
75	   * to this queue for later processing.
76	   */
77	  private final Queue<DatanodeDescriptor> cancelledNodes = new ArrayDeque<>();
78	
79	  /**
80	   * The numbe of blocks to process when moving blocks to pendingReplication
81	   * before releasing and reclaiming the namenode lock.
82	   */
83	  private int blocksPerLock;
84	
85	  /**
86	   * The number of blocks that have been checked on this tick.
87	   */
88	  private int numBlocksChecked = 0;
89	  /**
90	   * The maximum number of blocks to hold in PendingRep at any time.
91	   */
92	  private int pendingRepLimit;
93	
94	  /**
95	   * The list of blocks which have been placed onto the replication queue
96	   * and are waiting to be sufficiently replicated.
97	   */
98	  private final Map<DatanodeDescriptor, List<BlockInfo>>
99	      pendingRep = new HashMap<>();
100	
101	  private static final Logger LOG =
102	      LoggerFactory.getLogger(DatanodeAdminBackoffMonitor.class);
