118	              DFS_NAMENODE_DECOMMISSION_BACKOFF_MONITOR_PENDING_LIMIT,
119	          DFSConfigKeys.
120	              DFS_NAMENODE_DECOMMISSION_BACKOFF_MONITOR_PENDING_LIMIT_DEFAULT
121	      );
122	      this.pendingRepLimit = DFSConfigKeys.
123	          DFS_NAMENODE_DECOMMISSION_BACKOFF_MONITOR_PENDING_LIMIT_DEFAULT;
124	    }
125	    this.blocksPerLock = conf.getInt(
126	        DFSConfigKeys.
127	            DFS_NAMENODE_DECOMMISSION_BACKOFF_MONITOR_PENDING_BLOCKS_PER_LOCK,
128	        DFSConfigKeys.
129	            DFS_NAMENODE_DECOMMISSION_BACKOFF_MONITOR_PENDING_BLOCKS_PER_LOCK_DEFAULT
130	    );
131	    if (blocksPerLock <= 0) {
132	      LOG.error("{} is set to an invalid value, it must be greater than "+
133	              "zero. Defaulting to {}",
134	          DFSConfigKeys.
135	              DFS_NAMENODE_DECOMMISSION_BACKOFF_MONITOR_PENDING_BLOCKS_PER_LOCK,
136	          DFSConfigKeys.
137	              DFS_NAMENODE_DECOMMISSION_BACKOFF_MONITOR_PENDING_BLOCKS_PER_LOCK_DEFAULT);
138	      blocksPerLock =
139	          DFSConfigKeys.
140	              DFS_NAMENODE_DECOMMISSION_BACKOFF_MONITOR_PENDING_BLOCKS_PER_LOCK_DEFAULT;
141	    }
142	    LOG.info("Initialized the Backoff Decommission and Maintenance Monitor");
143	  }
