145	  /**
146	   * Queue a node to be removed from tracking. This method must be called
147	   * under the namenode write lock.
148	   * @param dn The datanode to stop tracking for decommission.
149	   */
150	  @Override
151	  public void stopTrackingNode(DatanodeDescriptor dn) {
152	    pendingNodes.remove(dn);
153	    cancelledNodes.add(dn);
154	  }
155	
156	  @Override
157	  public int getTrackedNodeCount() {
158	    return outOfServiceNodeBlocks.size();
159	  }
160	
161	  @Override
162	  public int getNumNodesChecked() {
163	    // We always check all nodes on each tick
164	    return outOfServiceNodeBlocks.size();
165	  }
166	
167	  @Override
168	  public void run() {
169	    LOG.debug("DatanodeAdminMonitorV2 is running.");
170	    if (!namesystem.isRunning()) {
171	      LOG.info("Namesystem is not running, skipping " +
172	          "decommissioning/maintenance checks.");
173	      return;
174	    }
175	    // Reset the checked count at beginning of each iteration
176	    numBlocksChecked = 0;
177	    // Check decommission or maintenance progress.
178	    try {
179	      namesystem.writeLock();
180	      try {
181	        /**
182	         * Other threads can modify the pendingNode list and the cancelled
183	         * node list, so we must process them under the NN write lock to
184	         * prevent any concurrent modifications.
185	         *
186	         * Always process the cancelled list before the pending list, as
187	         * it is possible for a node to be cancelled, and then quickly added
188	         * back again. If we process these the other way around, the added
189	         * node will be removed from tracking by the pending cancel.
190	         */
191	        processCancelledNodes();
192	        processPendingNodes();
193	      } finally {
194	        namesystem.writeUnlock();
195	      }
196	      // After processing the above, various parts of the check() method will
197	      // take and drop the read / write lock as needed. Aside from the
198	      // cancelled and pending lists, nothing outside of the monitor thread
199	      // modifies anything inside this class, so many things can be done
200	      // without any lock.
201	      check();
202	    } catch (Exception e) {
203	      LOG.warn("DatanodeAdminMonitor caught exception when processing node.",
204	          e);
205	    }
206	    if (numBlocksChecked + outOfServiceNodeBlocks.size() > 0) {
207	      LOG.info("Checked {} blocks this tick. {} nodes are now " +
208	          "in maintenance or transitioning state. {} nodes pending. {} " +
209	          "nodes waiting to be cancelled.",
210	          numBlocksChecked, outOfServiceNodeBlocks.size(), pendingNodes.size(),
211	          cancelledNodes.size());
212	    }
213	  }
214	
215	  /**
216	   * Move any pending nodes into outOfServiceNodeBlocks to initiate the
217	   * decommission or maintenance mode process.
218	   *
219	   * This method must be executed under the namenode write lock to prevent
220	   * the pendingNodes list from being modified externally.
221	   */
222	  private void processPendingNodes() {
223	    while (!pendingNodes.isEmpty() &&
224	        (maxConcurrentTrackedNodes == 0 ||
225	            outOfServiceNodeBlocks.size() < maxConcurrentTrackedNodes)) {
226	      outOfServiceNodeBlocks.put(pendingNodes.poll(), null);
227	    }
228	  }
229	
230	  /**
231	   * Process any nodes which have had their decommission or maintenance mode
232	   * cancelled by an administrator.
233	   *
234	   * This method must be executed under the
235	   * write lock to prevent the cancelledNodes list being modified externally.
236	   */
237	  private void processCancelledNodes() {
238	    while(!cancelledNodes.isEmpty()) {
239	      DatanodeDescriptor dn = cancelledNodes.poll();
240	      outOfServiceNodeBlocks.remove(dn);
241	      pendingRep.remove(dn);
242	    }
243	  }
244	
245	  /**
246	   * This method performs each of the steps to track a node from
247	   * decommissioning or entering maintenance to the end state.
248	   *
249	   * First, any newly added nodes are scanned.
250	   *
251	   * Then any expired maintenance nodes are handled.
252	   *
253	   * Next the pendingRep map is scanned and all blocks which are now
254	   * sufficiently replicated are removed
255	   *
256	   * Then new blocks are moved to pendingRep
257	   *
258	   * Finally we check if any nodes have completed the replication process and
259	   * if so move them to their final states.
260	   *
261	   * This methods which this method calls will take and release the namenode
262	   * read and write lock several times.
263	   *
264	   */
265	  private void check() {
266	    final List<DatanodeDescriptor> toRemove = new ArrayList<>();
267	
268	    if (outOfServiceNodeBlocks.size() == 0) {
269	      // No nodes currently being tracked so simply return
270	      return;
271	    }
272	
273	    // Check if there are any pending nodes to process, ie those where the
274	    // storage has not been scanned yet. For all which are pending, scan
275	    // the storage and load the under-replicated block list into
276	    // outOfServiceNodeBlocks. As this does not modify any external structures
277	    // it can be done under the namenode *read* lock, and the lock can be
278	    // dropped between each storage on each node.
279	    //
280	    // TODO - This is an expensive call, depending on how many nodes are
281	    //        to be processed, but it requires only the read lock and it will
282	    //        be dropped and re-taken frequently. We may want to throttle this
283	    //        to process only a few nodes per iteration.
284	    outOfServiceNodeBlocks.keySet()
285	        .stream()
286	        .filter(n -> outOfServiceNodeBlocks.get(n) == null)
287	        .forEach(n -> scanDatanodeStorage(n, true));
288	
289	    processMaintenanceNodes();
290	    // First check the pending replication list and remove any blocks
291	    // which are now replicated OK. This list is constrained in size so this
292	    // call should not be overly expensive.
293	    processPendingReplication();
294	
295	    // Now move a limited number of blocks to pending
296	    moveBlocksToPending();
297	
298	    // Check if any nodes have reached zero blocks and also update the stats
299	    // exposed via JMX for all nodes still being processed.
300	    checkForCompletedNodes(toRemove);
301	
302	    // Finally move the nodes to their final state if they are ready.
303	    processCompletedNodes(toRemove);
304	  }
305	
306	  /**
307	   * Checks for any nodes which are in maintenance and if maintenance has
308	   * expired, the node will be moved back to in_service (or dead) as required.
309	   */
310	  private void processMaintenanceNodes() {
311	    // Check for any maintenance state nodes which need to be expired
312	    namesystem.writeLock();
313	    try {
314	      for (DatanodeDescriptor dn : outOfServiceNodeBlocks.keySet()) {
315	        if (dn.isMaintenance() && dn.maintenanceExpired()) {
316	          // If maintenance expires, stop tracking it. This can be an
317	          // expensive call, as it may need to invalidate blocks. Therefore
318	          // we can yield and retake the write lock after each node
319	          //
320	          // The call to stopMaintenance makes a call to stopTrackingNode()
321	          // which added the node to the cancelled list. Therefore expired
322	          // maintenance nodes do not need to be added to the toRemove list.
323	          dnAdmin.stopMaintenance(dn);
324	          namesystem.writeUnlock();
325	          namesystem.writeLock();
326	        }
327	      }
328	    } finally {
329	      namesystem.writeUnlock();
330	    }
331	  }
332	
333	  /**
334	   * Loop over all nodes in the passed toRemove list and move the node to
335	   * the required end state. This will also remove any entries from
336	   * outOfServiceNodeBlocks and pendingRep for the node if required.
337	   *
338	   * @param toRemove The list of nodes to process for completion.
339	   */
340	  private void processCompletedNodes(List<DatanodeDescriptor> toRemove) {
341	    if (toRemove.size() == 0) {
342	      // If there are no nodes to process simply return and avoid
343	      // taking the write lock at all.
344	      return;
345	    }
346	    namesystem.writeLock();
347	    try {
348	      for (DatanodeDescriptor dn : toRemove) {
349	        final boolean isHealthy =
350	            blockManager.isNodeHealthyForDecommissionOrMaintenance(dn);
351	        if (isHealthy) {
352	          if (dn.isDecommissionInProgress()) {
353	            dnAdmin.setDecommissioned(dn);
354	            outOfServiceNodeBlocks.remove(dn);
355	            pendingRep.remove(dn);
356	          } else if (dn.isEnteringMaintenance()) {
357	            // IN_MAINTENANCE node remains in the outOfServiceNodeBlocks to
358	            // to track maintenance expiration.
359	            dnAdmin.setInMaintenance(dn);
360	            pendingRep.remove(dn);
361	          } else if (dn.isInService()) {
362	            // Decom / maint was cancelled and the node is yet to be processed
363	            // from cancelledNodes
364	            LOG.info("Node {} completed decommission and maintenance " +
365	                "but has been moved back to in service", dn);
366	            pendingRep.remove(dn);
367	            outOfServiceNodeBlocks.remove(dn);
368	            continue;
369	          } else {
370	            // Should not happen
371	            LOG.error("Node {} is in an unexpected state {} and has been "+
372	                    "removed from tracking for decommission or maintenance",
373	                dn, dn.getAdminState());
374	            pendingRep.remove(dn);
375	            outOfServiceNodeBlocks.remove(dn);
376	            continue;
377	          }
378	          LOG.info("Node {} is sufficiently replicated and healthy, "
379	              + "marked as {}.", dn, dn.getAdminState());
380	        } else {
381	          LOG.info("Node {} isn't healthy."
382	                  + " It needs to replicate {} more blocks."
383	                  + " {} is still in progress.", dn,
384	              getPendingCountForNode(dn), dn.getAdminState());
385	        }
386	      }
387	    } finally {
388	      namesystem.writeUnlock();
389	    }
390	  }
391	
392	  /**
393	   * Loop over all nodes and check for any which have zero unprocessed or
394	   * pending blocks. If the node has zero blocks pending, the storage is
395	   * rescanned to ensure no transient blocks were missed on the first pass.
396	   *
397	   * If, after rescan the number of blocks pending replication is zero, the
398	   * node is added to the passed removeList which will later be processed to
399	   * complete the decommission or entering maintenance process.
400	   *
401	   * @param removeList Nodes which have zero pending blocks are added to this
402	   *                   list.
403	   */
404	  private void checkForCompletedNodes(List<DatanodeDescriptor> removeList) {
405	    for (DatanodeDescriptor dn : outOfServiceNodeBlocks.keySet()) {
406	      // If the node is already in maintenance, we don't need to perform
407	      // any further checks on it.
408	      if (dn.isInMaintenance()) {
409	        LOG.debug("Node {} is currently in maintenance", dn);
410	        continue;
411	      } else if (!dn.isInService()) {
412	        // A node could be inService if decom or maint has been cancelled, but
413	        // the cancelled list is yet to be processed. We don't need to check
414	        // inService nodes here
415	        int outstandingBlocks = getPendingCountForNode(dn);
416	        if (outstandingBlocks == 0) {
417	          scanDatanodeStorage(dn, false);
418	          outstandingBlocks = getPendingCountForNode(dn);
419	        }
420	        LOG.info("Node {} has {} blocks yet to process", dn, outstandingBlocks);
421	        if (outstandingBlocks == 0) {
422	          removeList.add(dn);
423	        }
424	      }
425	    }
426	  }
427	
428	  /**
429	   * Returns the number of block pending for the given node by adding those
430	   * blocks in pendingRep and outOfServiceNodeBlocks.
431	   *
432	   * @param dn The datanode to return the count for
433	   * @return The total block count, or zero if none are pending
434	   */
435	  private int getPendingCountForNode(DatanodeDescriptor dn) {
436	    int count = 0;
437	    HashMap<BlockInfo, Integer> blocks = outOfServiceNodeBlocks.get(dn);
438	    if (blocks != null) {
439	      count += blocks.size();
440	    }
441	    List<BlockInfo> pendingBlocks = pendingRep.get(dn);
442	    if (pendingBlocks != null) {
443	      count += pendingBlocks.size();
444	    }
445	    return count;
446	  }
447	
448	  /**
449	   * Iterate across all nodes in outOfServiceNodeBlocks which have blocks yet
450	   * to be processed.
451	   *
452	   * The block is removed from outOfServiceNodeBlocks and if it needs
453	   * replication it is added to the pendingRep map and also to the
454	   * BlockManager replication queue.
455	   *
456	   * Any block that does not need replication is discarded.
457	   *
458	   * The method will return when there are the pendingRep map has
459	   * pendingRepLimit blocks or there are no further blocks to process.
460	   */
461	  private void moveBlocksToPending() {
462	    int blocksProcessed = 0;
463	    int pendingCount = getPendingCount();
464	    int yetToBeProcessed = getYetToBeProcessedCount();
465	
466	    if (pendingCount == 0 && yetToBeProcessed == 0) {
467	      // There are no blocks to process so just return
468	      LOG.debug("There are no pending or blocks yet to be processed");
469	      return;
470	    }
471	
472	    namesystem.writeLock();
473	    try {
474	      long repQueueSize = blockManager.getLowRedundancyBlocksCount();
475	
476	      LOG.info("There are {} blocks pending replication and the limit is "+
477	          "{}. A further {} blocks are waiting to be processed. "+
478	          "The replication queue currently has {} blocks",
479	          pendingCount, pendingRepLimit, yetToBeProcessed, repQueueSize);
480	
481	      if (pendingCount >= pendingRepLimit) {
482	        // Only add more blocks to the replication queue if we don't already
483	        // have too many pending
484	        return;
485	      }
486	
487	      // Create a "Block Iterator" for each node decommissioning or entering
488	      // maintenance. These iterators will be used "round robined" to add blocks
489	      // to the replication queue and PendingRep
490	      HashMap<DatanodeDescriptor, Iterator<BlockInfo>>
491	          iterators = new HashMap<>();
492	      for (Map.Entry<DatanodeDescriptor, HashMap<BlockInfo, Integer>> e
493	          : outOfServiceNodeBlocks.entrySet()) {
494	        iterators.put(e.getKey(), e.getValue().keySet().iterator());
495	      }
496	
497	      // Now loop until we fill the pendingRep map with pendingRepLimit blocks
498	      // or run out of blocks to add.
499	      Iterator<DatanodeDescriptor> nodeIter =
500	          Iterables.cycle(iterators.keySet()).iterator();
501	      while (nodeIter.hasNext()) {
502	        // Cycle through each node with blocks which still need processed
503	        DatanodeDescriptor dn = nodeIter.next();
504	        Iterator<BlockInfo> blockIt = iterators.get(dn);
505	        while (blockIt.hasNext()) {
506	          // Process the blocks for the node until we find one that needs
507	          // replication
508	          if (blocksProcessed >= blocksPerLock) {
509	            blocksProcessed = 0;
510	            namesystem.writeUnlock();
511	            namesystem.writeLock();
512	          }
513	          blocksProcessed++;
514	          if (nextBlockAddedToPending(blockIt, dn)) {
515	            // Exit the inner "block" loop so an iterator for the next datanode
516	            // is used for the next block.
517	            pendingCount++;
518	            break;
519	          }
520	        }
521	        if (!blockIt.hasNext()) {
522	          // remove the iterator as there are no blocks left in it
523	          nodeIter.remove();
524	        }
525	        if (pendingCount >= pendingRepLimit) {
526	          // We have scheduled the limit of blocks for replication, so do
527	          // not add any more
528	          break;
529	        }
530	      }
531	    } finally {
532	      namesystem.writeUnlock();
533	    }
534	    LOG.debug("{} blocks are now pending replication", pendingCount);
535	  }
536	
537	  /**
538	   * Takes and removes the next block from the given iterator and checks if it
539	   * needs additional replicas. If it does, it will be scheduled for
540	   * reconstruction and added to the pendingRep map.
541	   * @param it The iterator to take the next block from
542	   * @param dn The datanodeDescriptor the iterator applies to
543	   * @return True if the block needs replication, otherwise false
544	   */
545	  private boolean nextBlockAddedToPending(Iterator<BlockInfo> it,
546	      DatanodeDescriptor dn) {
547	    BlockInfo block = it.next();
548	    it.remove();
549	    numBlocksChecked++;
550	    if (!isBlockReplicatedOk(dn, block, true, null)) {
551	      pendingRep.computeIfAbsent(dn, k -> new LinkedList<>()).add(block);
552	      return true;
553	    }
554	    return false;
555	  }
556	
557	  private int getPendingCount() {
558	    if (pendingRep.size() == 0) {
559	      return 0;
560	    }
561	    return pendingRep.values()
562	        .stream()
563	        .map(a -> a.size())
564	        .reduce(0, (a, b) -> a + b);
565	  }
566	
567	  private int getYetToBeProcessedCount() {
568	    if (outOfServiceNodeBlocks.size() == 0) {
569	      return 0;
570	    }
571	    return outOfServiceNodeBlocks.values()
572	        .stream()
573	        .map(a -> a.size())
574	        .reduce(0, (a, b) -> a + b);
575	  }
576	
577	  /**
578	   * Scan all the blocks held on a datanodes. For a node being decommissioned
579	   * we assume that the majority of blocks on the node will need to have new
580	   * replicas made, and therefore we do not check if they are under replicated
581	   * here and instead add them to the list of blocks to track.
582	   *
583	   * For a node being moved into maintenance, we assume most blocks will be
584	   * replicated OK and hence we do check their under-replicated status here,
585	   * hopefully reducing the number of blocks to track.
586	   *
587	   * On a re-scan (initalScan = false) we assume the node has been processed
588	   * already, and hence there should be few under-replicated blocks, so we
589	   * check the under-replicated status before adding the blocks to the
590	   * tracking list.
591	   *
592	   * This means that for a node being decomission there should be a large
593	   * number of blocks to process later but for maintenance, a smaller number.
594	   *
595	   * As this method does not schedule any blocks for reconstuction, this
596	   * scan can be performed under the namenode readlock, and the lock is
597	   * dropped and reaquired for each storage on the DN.
598	   *
599	   * @param dn - The datanode to process
600	   * @param initialScan - True is this is the first time scanning the node
601	   *                    or false if it is a rescan.
602	   */
603	  private void scanDatanodeStorage(DatanodeDescriptor dn,
604	                                   Boolean initialScan) {
605	    HashMap<BlockInfo, Integer> blockList = outOfServiceNodeBlocks.get(dn);
606	    if (blockList == null) {
607	      blockList = new HashMap<>();
608	      outOfServiceNodeBlocks.put(dn, blockList);
609	    }
610	
611	    DatanodeStorageInfo[] storage;
612	    namesystem.readLock();
613	    try {
614	      storage = dn.getStorageInfos();
615	    } finally {
616	      namesystem.readUnlock();
617	    }
618	
619	    for (DatanodeStorageInfo s : storage) {
620	      namesystem.readLock();
621	      try {
622	        // As the lock is dropped and re-taken between each storage, we need
623	        // to check the storage is still present before processing it, as it
624	        // may have been removed.
625	        if (dn.getStorageInfo(s.getStorageID()) == null) {
626	          continue;
627	        }
628	        Iterator<BlockInfo> it = s.getBlockIterator();
629	        while (it.hasNext()) {
630	          BlockInfo b = it.next();
631	          if (!initialScan || dn.isEnteringMaintenance()) {
632	            // this is a rescan, so most blocks should be replicated now,
633	            // or this node is going into maintenance. On a healthy
634	            // cluster using racks or upgrade domain, a node should be
635	            // able to go into maintenance without replicating many blocks
636	            // so we will check them immediately.
637	            if (!isBlockReplicatedOk(dn, b, false, null)) {
638	              blockList.put(b, null);
639	            }
640	          } else {
641	            blockList.put(b, null);
642	          }
643	          numBlocksChecked++;
644	        }
645	      } finally {
646	        namesystem.readUnlock();
647	      }
648	    }
649	  }
650	
651	  /**
652	   * Process the list of pendingReplication Blocks. These are the blocks
653	   * which have been moved from outOfServiceNodeBlocks, confirmed to be
654	   * under-replicated and were added to the blockManager replication
655	   * queue.
656	   *
657	   * Any blocks which have been confirmed to be replicated sufficiently are
658	   * removed from the list.
659	   *
660	   * The datanode stats are also updated in this method, updating the total
661	   * pending block count, the number of blocks in PendingRep which are in
662	   * open files and the number of blocks in PendingRep which are only on
663	   * out of service nodes.
664	   *
665	   * As this method makes changes to the replication queue, it acquires the
666	   * namenode write lock while it runs.
667	   */
668	  private void processPendingReplication() {
669	    namesystem.writeLock();
670	    try {
671	      for (Iterator<Map.Entry<DatanodeDescriptor, List<BlockInfo>>>
672	           entIt = pendingRep.entrySet().iterator(); entIt.hasNext();) {
673	        Map.Entry<DatanodeDescriptor, List<BlockInfo>> entry = entIt.next();
674	        DatanodeDescriptor dn = entry.getKey();
675	        List<BlockInfo> blocks = entry.getValue();
676	        if (blocks == null) {
677	          // should not be able to happen
678	          entIt.remove();
679	          continue;
680	        }
681	        Iterator<BlockInfo> blockIt =  blocks.iterator();
682	        BlockStats suspectBlocks = new BlockStats();
683	        while(blockIt.hasNext()) {
684	          BlockInfo b = blockIt.next();
685	          if (isBlockReplicatedOk(dn, b, true, suspectBlocks)) {
686	            blockIt.remove();
687	          }
688	          numBlocksChecked++;
689	        }
690	        if (blocks.size() == 0) {
691	          entIt.remove();
692	        }
693	        // Update metrics for this datanode.
694	        dn.getLeavingServiceStatus().set(
695	            suspectBlocks.getOpenFileCount(),
696	            suspectBlocks.getOpenFiles(),
697	            getPendingCountForNode(dn),
698	            suspectBlocks.getOutOfServiceBlockCount());
699	      }
700	    } finally {
701	      namesystem.writeUnlock();
702	    }
703	  }
704	
705	  /**
706	   * Checks if a block is sufficiently replicated and optionally schedules
707	   * it for reconstruction if it is not.
708	   *
709	   * If a BlockStats object is passed, this method will also update it if the
710	   * block is part of an open file or only on outOfService nodes.
711	   *
712	   * @param datanode The datanode the block belongs to
713	   * @param block The block to check
714	   * @param scheduleReconStruction Whether to add the block to the replication
715	   *                               queue if it is not sufficiently replicated.
716	   *                               Passing true will add it to the replication
717	   *                               queue, and false will not.
718	   * @param suspectBlocks If non-null check if the block is part of an open
719	   *                      file or only on out of service nodes and update the
720	   *                      passed object accordingly.
721	   * @return
722	   */
723	  private boolean isBlockReplicatedOk(DatanodeDescriptor datanode,
724	      BlockInfo block, Boolean scheduleReconStruction,
725	      BlockStats suspectBlocks) {
726	    if (blockManager.blocksMap.getStoredBlock(block) == null) {
727	      LOG.trace("Removing unknown block {}", block);
728	      return true;
729	    }
730	
731	    long bcId = block.getBlockCollectionId();
732	    if (bcId == INodeId.INVALID_INODE_ID) {
733	      // Orphan block, will be invalidated eventually. Skip.
734	      return false;
735	    }
736	
737	    final BlockCollection bc = blockManager.getBlockCollection(block);
738	    final NumberReplicas num = blockManager.countNodes(block);
739	    final int liveReplicas = num.liveReplicas();
740	
741	    // Schedule low redundancy blocks for reconstruction
742	    // if not already pending.
743	    boolean isDecommission = datanode.isDecommissionInProgress();
744	    boolean isMaintenance = datanode.isEnteringMaintenance();
745	
746	    boolean neededReconstruction = isDecommission ?
747	        blockManager.isNeededReconstruction(block, num) :
748	        blockManager.isNeededReconstructionForMaintenance(block, num);
749	    if (neededReconstruction && scheduleReconStruction) {
750	      if (!blockManager.neededReconstruction.contains(block) &&
751	          blockManager.pendingReconstruction.getNumReplicas(block) == 0 &&
752	          blockManager.isPopulatingReplQueues()) {
753	        // Process these blocks only when active NN is out of safe mode.
754	        blockManager.neededReconstruction.add(block,
755	            liveReplicas, num.readOnlyReplicas(),
756	            num.outOfServiceReplicas(),
757	            blockManager.getExpectedRedundancyNum(block));
758	      }
759	    }
760	
761	    if (suspectBlocks != null) {
762	      // Only if we pass a BlockStats object should we do these
763	      // checks, as they should only be checked when processing PendingRep.
764	      if (bc.isUnderConstruction()) {
765	        INode ucFile = namesystem.getFSDirectory().getInode(bc.getId());
766	        if (!(ucFile instanceof INodeFile) ||
767	            !ucFile.asFile().isUnderConstruction()) {
768	          LOG.warn("File {} is not under construction. Skipping add to " +
769	              "low redundancy open files!", ucFile.getLocalName());
770	        } else {
771	          suspectBlocks.addOpenFile(ucFile.getId());
772	        }
773	      }
774	      if ((liveReplicas == 0) && (num.outOfServiceReplicas() > 0)) {
775	        suspectBlocks.incrementOutOfServiceBlocks();
776	      }
777	    }
778	
779	    // Even if the block is without sufficient redundancy,
780	    // it might not block decommission/maintenance if it
781	    // has sufficient redundancy.
782	    if (dnAdmin.isSufficient(block, bc, num, isDecommission, isMaintenance)) {
783	      return true;
784	    }
785	    return false;
786	  }
787	
788	  static class BlockStats {
789	    private LightWeightHashSet<Long> openFiles =
790	        new LightWeightLinkedSet<>();
791	    private int openFileBlockCount = 0;
792	    private int outOfServiceBlockCount = 0;
793	
794	    public void addOpenFile(long id) {
795	      // Several blocks can be part of the same file so track how
796	      // many adds we get, as the same file could be added several times
797	      // for different blocks.
798	      openFileBlockCount++;
799	      openFiles.add(id);
800	    }
801	
802	    public void incrementOutOfServiceBlocks() {
803	      outOfServiceBlockCount++;
804	    }
805	
806	    public LightWeightHashSet<Long> getOpenFiles() {
807	      return openFiles;
808	    }
809	
810	    public int getOpenFileCount() {
811	      return openFileBlockCount;
812	    }
813	
814	    public int getOutOfServiceBlockCount() {
815	      return outOfServiceBlockCount;
816	    }
817	  }
818	}

